def solve(inputs: dict) -> float:
    # Get the number as a string
    n = str(int(inputs['N']))
    digits = [int(d) for d in n]

    # Reading from the right, double every second digit
    # Position 1 from right = last digit (not doubled)
    # Position 2 from right = second to last (doubled)
    result = []
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:  # every second digit from right (0-indexed, so positions 1,3,5,...)
            d *= 2
            if d > 9:
                d -= 9
        result.append(d)

    return sum(result)

